    elif t == "CIRCLE": d.update(c=tuple(e.dxf.center), r=e.dxf.radius)
    elif t == "ARC": d.update(c=tuple(e.dxf.center), r=e.dxf.radius, a=(e.dxf.start_angle, e.dxf.end_angle))
